--
-- Name: set_duracion_sesion_uso(); Type: FUNCTION; Schema: public; Owner: gymkeep
--

CREATE FUNCTION public.set_duracion_sesion_uso() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.fecha_fin IS NOT NULL AND NEW.fecha_inicio IS NOT NULL THEN
        NEW.duracion_segundos = GREATEST(
            0,
            FLOOR(EXTRACT(EPOCH FROM (NEW.fecha_fin - NEW.fecha_inicio)))::INTEGER
        );
    END IF;
    RETURN NEW;
END;
$$;


