CREATE TABLE public.zonas (
    id bigint NOT NULL,
    sucursal_id bigint NOT NULL,
    nombre character varying(120) NOT NULL,
    descripcion character varying(250),
    piso character varying(30),
    activa boolean DEFAULT true NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.zonas OWNER TO gymkeep;

--
-- Name: v_camaras; Type: VIEW; Schema: public; Owner: gymkeep
--

CREATE VIEW public.v_camaras AS
 SELECT c.id AS "Id",
    c.codigo AS "C??digo",
    c.nombre AS "C??mara",
    s.nombre AS "Sucursal",
    COALESCE(z.nombre, '-'::character varying) AS "Zona",
    initcap((c.estado)::text) AS "Estado",
        CASE
            WHEN (c.ancho_px IS NULL) THEN '-'::text
            ELSE ((c.ancho_px || ' x '::text) || c.alto_px)
        END AS "Resoluci??n",
    COALESCE((round(c.fps_configurado))::text, '-'::text) AS "FPS",
    to_char((c.ultima_conexion AT TIME ZONE 'America/Santiago'::text), 'DD-MM-YYYY HH24:MI:SS'::text) AS "??ltima conexi??n",
    ( SELECT count(*) AS count
           FROM public.camara_equipos ce
          WHERE ((ce.camara_id = c.id) AND ce.activo)) AS "M??quinas con zona"
   FROM ((public.camaras c
     JOIN public.sucursales s ON ((s.id = c.sucursal_id)))
     LEFT JOIN public.zonas z ON ((z.id = c.zona_id)))
  ORDER BY c.codigo;


ALTER VIEW public.v_camaras OWNER TO gymkeep;

--
-- Name: v_costos_por_mes; Type: VIEW; Schema: public; Owner: gymkeep
--

CREATE VIEW public.v_costos_por_mes AS
 SELECT to_char(date_trunc('month'::text, (fecha_inicio AT TIME ZONE 'America/Santiago'::text)), 'YYYY-MM'::text) AS "Mes",
    initcap((tipo)::text) AS "Tipo",
    count(*) AS "Mantenciones",
    ('$ '::text || replace(to_char(round(COALESCE(sum(costo_total), (0)::numeric)), 'FM999,999,999,999'::text), ','::text, '.'::text)) AS "Costo total"
   FROM public.mantenimientos m
  GROUP BY (to_char(date_trunc('month'::text, (fecha_inicio AT TIME ZONE 'America/Santiago'::text)), 'YYYY-MM'::text)), (initcap((tipo)::text))
  ORDER BY (to_char(date_trunc('month'::text, (fecha_inicio AT TIME ZONE 'America/Santiago'::text)), 'YYYY-MM'::text)) DESC, (initcap((tipo)::text));


ALTER VIEW public.v_costos_por_mes OWNER TO gymkeep;

--
-- Name: v_equipos; Type: VIEW; Schema: public; Owner: gymkeep
--

CREATE VIEW public.v_equipos AS
 SELECT e.id AS "Id",
    e.codigo_activo AS "C??digo",
    e.nombre AS "Equipo",
    initcap((COALESCE(e.categoria, '-'::character varying))::text) AS "Categor??a",
    concat_ws(' '::text, e.marca, e.modelo) AS "Marca y modelo",
    s.nombre AS "Sucursal",
    COALESCE(z.nombre, '-'::character varying) AS "Zona",
    (upper("left"(replace((e.estado)::text, '_'::text, ' '::text), 1)) || substr(replace((e.estado)::text, '_'::text, ' '::text), 2)) AS "Estado",
    to_char((e.fecha_instalacion)::timestamp with time zone, 'DD-MM-YYYY'::text) AS "Instalado",
    COALESCE(i.abiertas, (0)::bigint) AS "Incidencias abiertas",
    COALESCE(i.total, (0)::bigint) AS "Incidencias totales",
    COALESCE(m.total, (0)::bigint) AS "Mantenciones",
    ('$ '::text || replace(to_char(round(COALESCE(m.costo, (0)::numeric)), 'FM999,999,999,999'::text), ','::text, '.'::text)) AS "Costo en mantenci??n",
    round(((COALESCE(u.segundos, (0)::bigint))::numeric / 3600.0), 1) AS "Horas de uso"
   FROM (((((public.equipos e
     JOIN public.sucursales s ON ((s.id = e.sucursal_id)))
     LEFT JOIN public.zonas z ON ((z.id = e.zona_id)))
     LEFT JOIN LATERAL ( SELECT count(*) AS total,
            count(*) FILTER (WHERE (incidencias.estado = ANY (ARRAY['pendiente'::public.estado_incidencia, 'en_proceso'::public.estado_incidencia]))) AS abiertas
           FROM public.incidencias
          WHERE (incidencias.equipo_id = e.id)) i ON (true))
     LEFT JOIN LATERAL ( SELECT count(*) AS total,
            sum(mantenimientos.costo_total) AS costo
           FROM public.mantenimientos
          WHERE (mantenimientos.equipo_id = e.id)) m ON (true))
     LEFT JOIN LATERAL ( SELECT sum(sesiones_uso.duracion_segundos) AS segundos
           FROM public.sesiones_uso
          WHERE ((sesiones_uso.equipo_id = e.id) AND ((sesiones_uso.estado)::text <> 'descartada'::text))) u ON (true))
  ORDER BY e.codigo_activo;


ALTER VIEW public.v_equipos OWNER TO gymkeep;

--
-- Name: v_incidencias; Type: VIEW; Schema: public; Owner: gymkeep
--

CREATE VIEW public.v_incidencias AS
 SELECT i.id AS "Id",
    to_char((i.fecha_reporte AT TIME ZONE 'America/Santiago'::text), 'DD-MM-YYYY HH24:MI'::text) AS "Reportada",
    (((e.codigo_activo)::text || ' ?? '::text) || (e.nombre)::text) AS "Equipo",
    t.nombre AS "Falla",
    initcap((i.prioridad)::text) AS "Prioridad",
    (upper("left"(replace((i.estado)::text, '_'::text, ' '::text), 1)) || substr(replace((i.estado)::text, '_'::text, ' '::text), 2)) AS "Estado",
    upper((i.origen)::text) AS "Origen",
    COALESCE(i.reportado_por, '-'::character varying) AS "Reportada por",
    COALESCE(i.descripcion, ''::text) AS "Descripci??n",
    to_char((i.fecha_resolucion AT TIME ZONE 'America/Santiago'::text), 'DD-MM-YYYY HH24:MI'::text) AS "Resuelta",
    round((EXTRACT(epoch FROM (COALESCE(i.fecha_resolucion, now()) - i.fecha_reporte)) / 86400.0), 1) AS "D??as abierta"
   FROM ((public.incidencias i
     JOIN public.equipos e ON ((e.id = i.equipo_id)))
     JOIN public.tipos_falla t ON ((t.id = i.tipo_falla_id)))
  ORDER BY i.fecha_reporte DESC;


ALTER VIEW public.v_incidencias OWNER TO gymkeep;

--
-- Name: v_mantenimientos; Type: VIEW; Schema: public; Owner: gymkeep
--

CREATE VIEW public.v_mantenimientos AS
 SELECT m.id AS "Id",
    to_char((m.fecha_inicio AT TIME ZONE 'America/Santiago'::text), 'DD-MM-YYYY'::text) AS "Fecha",
    (((e.codigo_activo)::text || ' ?? '::text) || (e.nombre)::text) AS "Equipo",
    initcap((m.tipo)::text) AS "Tipo",
    COALESCE(m.tecnico, '-'::character varying) AS "T??cnico",
    COALESCE(m.proveedor, '-'::character varying) AS "Proveedor",
    m.descripcion AS "Descripci??n",
        CASE
            WHEN (m.costo_total IS NULL) THEN '-'::text
            ELSE ('$ '::text || replace(to_char(round(m.costo_total), 'FM999,999,999,999'::text), ','::text, '.'::text))
        END AS "Costo",
        CASE
            WHEN (m.fecha_fin IS NULL) THEN 'En curso'::text
            ELSE ((GREATEST((1)::numeric, round((EXTRACT(epoch FROM (m.fecha_fin - m.fecha_inicio)) / 3600.0))))::integer || ' h'::text)
        END AS "Duraci??n",
    to_char((m.proximo_mantenimiento)::timestamp with time zone, 'DD-MM-YYYY'::text) AS "Pr??xima",
    m.incidencia_id AS "Incidencia"
   FROM (public.mantenimientos m
     JOIN public.equipos e ON ((e.id = m.equipo_id)))
  ORDER BY m.fecha_inicio DESC;


ALTER VIEW public.v_mantenimientos OWNER TO gymkeep;

--
-- Name: v_sesiones_uso; Type: VIEW; Schema: public; Owner: gymkeep
--

CREATE VIEW public.v_sesiones_uso AS
 SELECT su.id AS "Id",
    (((e.codigo_activo)::text || ' ?? '::text) || (e.nombre)::text) AS "Equipo",
    COALESCE(c.codigo, '-'::character varying) AS "C??mara",
    to_char((su.fecha_inicio AT TIME ZONE 'America/Santiago'::text), 'DD-MM-YYYY HH24:MI:SS'::text) AS "Inicio",
    to_char((su.fecha_fin AT TIME ZONE 'America/Santiago'::text), 'DD-MM-YYYY HH24:MI:SS'::text) AS "Fin",
        CASE
            WHEN (su.duracion_segundos IS NULL) THEN '-'::text
            WHEN (su.duracion_segundos >= 3600) THEN ((((su.duracion_segundos / 3600) || ' h '::text) || lpad((((su.duracion_segundos % 3600) / 60))::text, 2, '0'::text)) || ' min'::text)
            ELSE ((((su.duracion_segundos / 60) || ' min '::text) || lpad(((su.duracion_segundos % 60))::text, 2, '0'::text)) || ' s'::text)
        END AS "Duraci??n",
        CASE
            WHEN (su.confianza_promedio IS NULL) THEN '-'::text
            ELSE ((round((su.confianza_promedio * (100)::numeric)))::integer || ' %'::text)
        END AS "Confianza",
    initcap((su.estado)::text) AS "Estado",
    upper((su.origen)::text) AS "Origen"
   FROM ((public.sesiones_uso su
     JOIN public.equipos e ON ((e.id = su.equipo_id)))
     LEFT JOIN public.camaras c ON ((c.id = su.camara_id)))
  ORDER BY su.fecha_inicio DESC;


ALTER VIEW public.v_sesiones_uso OWNER TO gymkeep;

--
-- Name: vw_estado_equipos; Type: VIEW; Schema: public; Owner: gymkeep
--

CREATE VIEW public.vw_estado_equipos AS
 SELECT e.id AS equipo_id,
    e.codigo_activo,
    e.nombre AS equipo,
    e.estado,
    s.id AS sucursal_id,
    s.nombre AS sucursal,
    em.id AS empresa_id,
    COALESCE(em.nombre_fantasia, em.razon_social) AS empresa,
    z.nombre AS zona,
    count(i.id) FILTER (WHERE (i.estado = ANY (ARRAY['pendiente'::public.estado_incidencia, 'en_proceso'::public.estado_incidencia]))) AS incidencias_abiertas,
    count(i.id) FILTER (WHERE ((i.prioridad = 'urgente'::public.prioridad_incidencia) AND (i.estado = ANY (ARRAY['pendiente'::public.estado_incidencia, 'en_proceso'::public.estado_incidencia])))) AS urgentes_abiertas
   FROM ((((public.equipos e
     JOIN public.sucursales s ON ((s.id = e.sucursal_id)))
     JOIN public.empresas em ON ((em.id = s.empresa_id)))
     LEFT JOIN public.zonas z ON ((z.id = e.zona_id)))
     LEFT JOIN public.incidencias i ON ((i.equipo_id = e.id)))
  GROUP BY e.id, e.codigo_activo, e.nombre, e.estado, s.id, s.nombre, em.id, em.nombre_fantasia, em.razon_social, z.nombre;


ALTER VIEW public.vw_estado_equipos OWNER TO gymkeep;

--
-- Name: vw_uso_diario_equipos; Type: VIEW; Schema: public; Owner: gymkeep
--

CREATE VIEW public.vw_uso_diario_equipos AS
 SELECT equipo_id,
    date(fecha_inicio) AS fecha,
    count(*) FILTER (WHERE ((estado)::text = 'cerrada'::text)) AS sesiones,
    COALESCE(sum(duracion_segundos) FILTER (WHERE ((estado)::text = 'cerrada'::text)), (0)::bigint) AS segundos_uso,
    round(COALESCE(avg(confianza_promedio) FILTER (WHERE ((estado)::text = 'cerrada'::text)), (0)::numeric), 4) AS confianza_promedio
   FROM public.sesiones_uso
  GROUP BY equipo_id, (date(fecha_inicio));


ALTER VIEW public.vw_uso_diario_equipos OWNER TO gymkeep;

